  const absolute = Math.abs(offsetMinutes);
  return `${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`;
};

if (!/^\d{4}-\d{2}-\d{2}$/.test(requestedDate)) {
