    errorCode = 'REQUESTED_TIME_NOT_AVAILABLE';
    message = nearestSlots.length ? 'الوقت المطلوب غير متاح، وهذه أقرب المواعيد المتاحة' : 'الوقت المطلوب غير متاح حاليا';
  }
